    def largestPalindrome(self, n: int, k: int) -> str:
        if n == 1:
            for i in range(9, -1, -1):
                if i % k == 0:
                    return str(i)
            return ""

        half_len = (n + 1) // 2
        start = 10 ** (half_len - 1)
        end = 10 ** half_len - 1

        for i in range(end, start - 1, -1):
            s = str(i)
            if n % 2 == 0:
                palindrome = s + s[::-1]
            else:
                palindrome = s + s[:-1][::-1]

            num = int(palindrome)
            if num % k == 0:
                return palindrome

        return ""
