class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        """
        Finds the length of the shortest substring in s that matches p.

        Args:
            s: The string to search within.
            p: The pattern string with two '*' characters.

        Returns:
            The length of the shortest matching substring, or -1 if no match is found.
        """

        star1 = p.find('*')
        star2 = p.rfind('*')
        prefix = p[:star1]
        suffix = p[star2 + 1:]

        min_len = float('inf')

        for i in range(len(s) - len(prefix) - len(suffix) + 1):
            if s[i:i + len(prefix)] == prefix:
                for j in range(i + len(prefix), len(s) - len(suffix) + 1):
                    if s[j:j + len(suffix)] == suffix:
                        min_len = min(min_len, j - i + len(suffix))

        if min_len == float('inf'):
            if prefix == "" and suffix == "":
                return 0
            return -1
        else:
            return min_len
