    def countOfArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7

        even_count = m // 2
        odd_count = m - even_count

        dp = {}

        def solve(index, even_so_far, is_even):
            if index == n:
                if even_so_far == k:
                    return 1
                else:
                    return 0

            if (index, even_so_far, is_even) in dp:
                return dp[(index, even_so_far, is_even)]

            ans = 0

            # Choose even number
            ans = (ans + even_count * solve(index + 1, even_so_far + (1 if is_even else 0), True)) % MOD

            # Choose odd number
            ans = (ans + odd_count * solve(index + 1, even_so_far + (1 if not is_even else 0), False)) % MOD

            dp[(index, even_so_far, is_even)] = ans
            return ans

        return solve(0, 0, False)
